{
  "mode": "compile",
  "question": null,
  "asks_about":  "tolerance",
  "unresolved": [],
  "understanding": "This job is a pre-ride safety check and inflation of the Segway Xyber's tyres to their maximum sidewall pressure. The rider inspects for cracks or splits first to prevent catastrophic failure in traffic, then pumps the tyres to the sidewall limit and documents it with a photo.",
  "draft": {
    "key": "segway-xyber-tyre-check",
    "title": "Pre-Ride Tyre Pressure and Condition Check",
    "strictness": 2,
    "minimum_tier": "attested",
    "disqualifiers": [
      "Cracks in the tyre tread or sidewall",
      "Split sidewall"
    ],
    "releases": [
      "Safe to ride in city traffic and on gravel"
    ],
    "steps": [
      {
        "title": "Pre-Ride Tyre Inspection",
        "explanation": "Checking for cracks or splits before riding prevents catastrophic tyre failure at speed in city traffic.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "tyre_integrity",
            "kind": "choice",
            "prompt": "Check both tyres for any cracks or split sidewalls.",
            "source": "human",
            "required_at_strictness": 2,
            "choices": [
              "No cracks or splits found",
              "Cracks or split sidewall detected"
            ],
            "acceptance_rule": "matches",
            "acceptance_target": "No cracks or splits found",
            "guidance": "Inspect the entire circumference of both tyres. If any cracks or splits are found, the tyre is unsafe and must be replaced."
          }
        ]
      },
      {
        "title": "Inflate to Max Pressure",
        "explanation": "Pumping the tyres to the maximum pressure printed on the sidewall ensures optimal performance and safety.",
        "max_add_fields": 2,
        "fields": [
          {
            "key": "inflation_evidence",
            "kind": "photo",
            "prompt": "Take a photo showing the pump gauge reading alongside the max pressure text on the tyre sidewall.",
            "source": "camera",
            "required_at_strictness": 2,
            "acceptance_rule": "must_show",
            "acceptance_description": "The pump gauge showing the pressure matches the max pressure printed on the tyre sidewall.",
            "guidance": "Hold the pump gauge next to the tyre sidewall markings so both the pressure reading and the printed limit are clearly visible and legible."
          }
        ]
      }
    ]
  }
}
